/* landed Dragon or Griffin: its original standing picture, feet on the bottom of the frame */
.fighter.landed .mms-dragon,.fighter.landed .mms-griffin{background-size:contain!important;background-position:50% 100%!important}
.fighter.landed.blue .mms-dragon{background-image:url('myth/dragon_stand_blue.png')!important}.fighter.landed.red .mms-dragon{background-image:url('myth/dragon_stand_red.png')!important}
.fighter.landed.blue .mms-griffin{background-image:url('myth/griffin_stand_blue.png')!important}.fighter.landed.red .mms-griffin{background-image:url('myth/griffin_stand_red.png')!important}
